using Xunit;
using Moq;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using MediaBrowser.Controller.Entities;
using Microsoft.Extensions.Logging;

namespace MediaBrowser.Controller.Entities.Tests
{
    public class FolderTests
    {
        [Fact]
        public void RefreshLinkedChildren_LogsError_WhenResolvingShortcutFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<Folder>>();
            var folder = new TestFolder { Logger = loggerMock.Object };
            var fileSystemChildren = new List<FileSystemMetadata> { new FileSystemMetadata { FullName = "shortcut.txt", IsDirectory = false } };

            // Act
            folder.RefreshLinkedChildren(fileSystemChildren);

            // Assert
            loggerMock.Verify(logger => logger.LogError("Error resolving shortcut {0}", "shortcut.txt"), Times.Once);
        }

        [Fact]
        public void RefreshLinkedChildren_LogsError_WhenResolvingShortcutThrowsIOException()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<Folder>>();
            var folder = new TestFolder { Logger = loggerMock.Object };
            var fileSystemChildren = new List<FileSystemMetadata> { new FileSystemMetadata { FullName = "shortcut.txt", IsDirectory = false } };

            // Act
            folder.RefreshLinkedChildren(fileSystemChildren);

            // Assert
            loggerMock.Verify(logger => logger.LogError(It.IsAny<Exception>(), "Error resolving shortcut {0}", "shortcut.txt"), Times.Once);
        }
    }

    public class TestFolder : Folder
    {
        public new ILogger<Folder> Logger { get; set; }

        public override bool RefreshLinkedChildren(IEnumerable<FileSystemMetadata> fileSystemChildren)
        {
            return base.RefreshLinkedChildren(fileSystemChildren);
        }
    }
}
